const lang = $('Set IDs').first().json.panelist_language || 'en';
const tag = $('Check tag in allocation plan').first().json.tag_id || '';
let msg;
if (lang === 'es') msg = `✅ *¡Paquete recibido!* La etiqueta *${tag}* ha sido registrada correctamente.`;
else if (lang === 'fr') msg = `✅ *Colis recu !* L etiquette *${tag}* a ete enregistree avec succes.`;
else if (lang === 'ar') msg = `✅ *تم استلام الطرد!* تم تسجيل الملصق *${tag}* بنجاح.`;
else msg = `✅ *Parcel received!* The label *${tag}* has been registered successfully.`;
return [{ json: { response: msg, action: 'received', tag_id: tag } }];

const items = $input.all();
const ids = $('Set IDs').first().json;
const lang = ids.panelist_language || 'en';
const tag = ids.tag_id || '';

if (items.length === 0) {
  let noMsg;
  if (lang === 'es') noMsg = '📭 No se encontraron paquetes pendientes. Intentalo mas tarde.';
  else if (lang === 'fr') noMsg = '📭 Aucun colis en attente. Veuillez reessayer plus tard.';
  else if (lang === 'ar') noMsg = '📭 لم يتم العثور على طرود معلقة. يرجى المحاولة لاحقا.';
  else noMsg = '📭 No pending parcels found. Please try again later.';
  return [{ json: { response: noMsg, action: 'no_parcels', tag_id: tag } }];
}

let header;
if (lang === 'es') header = `📦 *Paquetes pendientes de envio:*\n?Cual estas enviando con la etiqueta *${tag}*?\nResponde con el numero:`;
else if (lang === 'fr') header = `📦 *Colis en attente envoi :*\nLequel envoyez-vous avec l etiquette *${tag}* ?\nRepondez avec le numero :`;
else if (lang === 'ar') header = `📦 *الطرود المعلقة للإرسال:*\nأيها ترسل بالملصق *${tag}*?\nأجب بالرقم:`;
else header = `📦 *Pending parcels to send:*\nWhich parcel are you sending with label *${tag}*?\nReply with the number:`;

let list = header + '\n\n';
items.forEach((item, i) => {
  const d = item.json;
  list += `*${i+1}.* ${d.destination_panelist_name || '?'} - ${d.destination_city_name || '?'} (${d.fecha_programada || '?'})\n`;
});

return [{ json: { response: list.trim(), action: 'assign_pending', tag_id: tag } }];

